<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Get Started with Aviaj | AI-Powered Business Travel & Expenses</title>
    <meta name="description" content="Create your Aviaj account today. Automate corporate travel booking, manage corporate cards, and reconcile expenses in real-time with no platform fees.">
    
    <!-- Modern Premium Typography -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    
    @vite(['resources/css/app.css', 'resources/js/app.js'])
</head>
<body class="font-sans text-[#0F172A] bg-[#FFFFFF] antialiased overflow-x-hidden">

    <!-- Top Announcement Banner -->
    <div class="bg-[#214D4D] text-white py-2 px-4 text-xs font-semibold tracking-wide text-center relative z-50 flex items-center justify-center space-x-2">
        <svg class="w-4 h-4 text-[#59BABA]" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/>
        </svg>
        <span>Get $500 for personal travel when your company joins Aviaj. <a href="#" class="underline hover:text-[#59BABA] transition-colors ml-1">Learn more</a></span>
    </div>

    <!-- Main Outer Container: Two Halves Grid -->
    <div class="min-h-[calc(100vh-32px)] grid lg:grid-cols-12 bg-white">
        
        <!-- Left Half: Registration Form -->
        <main id="get-started-main" class="lg:col-span-6 flex flex-col justify-between p-8 sm:p-12 md:p-16 max-w-xl mx-auto w-full">
            <!-- Brand Logo -->
            <div class="mb-10">
                <a href="/" class="flex items-center space-x-2">
                    <svg width="52" height="23" viewBox="0 0 52 23" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M12.6797 17.3906L11.2148 13.1719H4.92188L3.45703 17.3906H0L6.02344 0.878906H10.1016L16.1016 17.3906H12.6797ZM8.8125 5.82422C8.71875 5.55078 8.62695 5.27539 8.53711 4.99805C8.44727 4.7207 8.36914 4.4668 8.30273 4.23633C8.23633 4.00586 8.18164 3.81641 8.13867 3.66797C8.0957 3.51953 8.07031 3.4375 8.0625 3.42188C8.05469 3.44531 8.03125 3.53125 7.99219 3.67969C7.95312 3.82812 7.90039 4.01562 7.83398 4.24219C7.76758 4.46875 7.68945 4.7207 7.59961 4.99805C7.50977 5.27539 7.41797 5.55078 7.32422 5.82422L5.69531 10.5703H10.4414L8.8125 5.82422ZM21.8648 14.7305L25.0406 4.71094H28.4859L23.8102 17.3906H19.8727L15.3375 4.71094H18.818L21.8648 14.7305ZM29.6672 2.42578V0H32.9602V2.42578H29.6672ZM29.6672 17.3906V4.71094H32.9602V17.3906H29.6672ZM38.6648 17.625C38.0555 17.625 37.5105 17.541 37.0301 17.373C36.5496 17.2051 36.1414 16.959 35.8055 16.6348C35.4695 16.3105 35.2117 15.9102 35.032 15.4336C34.8523 14.957 34.7625 14.4141 34.7625 13.8047C34.7625 13.0547 34.8934 12.4238 35.1551 11.9121C35.4168 11.4004 35.7742 10.9863 36.2273 10.6699C36.6805 10.3535 37.2117 10.123 37.8211 9.97852C38.4305 9.83398 39.0789 9.75781 39.7664 9.75L42.4969 9.70312V9.05859C42.4969 8.59766 42.4559 8.21289 42.3738 7.9043C42.2918 7.5957 42.1727 7.34375 42.0164 7.14844C41.8602 6.95312 41.6668 6.81445 41.4363 6.73242C41.2059 6.65039 40.9422 6.60938 40.6453 6.60938C40.3719 6.60938 40.1277 6.63672 39.9129 6.69141C39.698 6.74609 39.5125 6.8418 39.3563 6.97852C39.2 7.11523 39.073 7.29883 38.9754 7.5293C38.8777 7.75977 38.8094 8.05078 38.7703 8.40234L35.3367 8.23828C35.4305 7.68359 35.6023 7.17773 35.8523 6.7207C36.1023 6.26367 36.448 5.86719 36.8895 5.53125C37.3309 5.19531 37.8738 4.93555 38.5184 4.75195C39.1629 4.56836 39.9188 4.47656 40.7859 4.47656C41.575 4.47656 42.2781 4.57422 42.8953 4.76953C43.5125 4.96484 44.0359 5.25586 44.4656 5.64258C44.8953 6.0293 45.2234 6.50391 45.45 7.06641C45.6766 7.62891 45.7898 8.28125 45.7898 9.02344V13.6406C45.7898 13.9375 45.8035 14.2031 45.8309 14.4375C45.8582 14.6719 45.909 14.8691 45.9832 15.0293C46.0574 15.1895 46.1629 15.3105 46.2996 15.3926C46.4363 15.4746 46.6141 15.5156 46.8328 15.5156C47.0828 15.5156 47.325 15.4922 47.5594 15.4453V17.2266C47.3641 17.2734 47.1883 17.3164 47.032 17.3555C46.8758 17.3945 46.7195 17.4258 46.5633 17.4492C46.407 17.4727 46.241 17.4922 46.0652 17.5078C45.8895 17.5234 45.6844 17.5312 45.45 17.5312C44.6219 17.5312 44.0105 17.3281 43.616 16.9219C43.2215 16.5156 42.9852 15.918 42.907 15.1289H42.8367C42.3992 15.918 41.8387 16.5312 41.1551 16.9688C40.4715 17.4062 39.6414 17.625 38.6648 17.625ZM42.4969 11.5195L40.8094 11.543C40.4578 11.5586 40.1238 11.5879 39.8074 11.6309C39.491 11.6738 39.2137 11.7637 38.9754 11.9004C38.7371 12.0371 38.5477 12.2344 38.407 12.4922C38.2664 12.75 38.1961 13.1016 38.1961 13.5469C38.1961 14.1484 38.3348 14.5957 38.6121 14.8887C38.8895 15.1816 39.2586 15.3281 39.7195 15.3281C40.1414 15.3281 40.5242 15.2383 40.868 15.0586C41.2117 14.8789 41.5027 14.6426 41.741 14.3496C41.9793 14.0566 42.1648 13.7188 42.2977 13.3359C42.4305 12.9531 42.4969 12.5625 42.4969 12.1641V11.5195ZM48.4945 2.42578V0H51.7875V2.42578H48.4945ZM48.4242 22.3711C47.9867 22.3711 47.6059 22.3613 47.2816 22.3418C46.9574 22.3223 46.6742 22.2969 46.432 22.2656V19.9453C46.5336 19.9609 46.6352 19.9727 46.7367 19.9805C46.8383 19.9883 46.9359 19.9922 47.0297 19.9922C47.3344 19.9922 47.5805 19.9609 47.768 19.8984C47.9555 19.8359 48.1039 19.7305 48.2133 19.582C48.3227 19.4336 48.3969 19.2383 48.4359 18.9961C48.475 18.7539 48.4945 18.4531 48.4945 18.0938V4.71094H51.7875V18.8906C51.7875 19.3984 51.725 19.8633 51.6 20.2852C51.475 20.707 51.2777 21.0742 51.0082 21.3867C50.7387 21.6992 50.391 21.9414 49.9652 22.1133C49.5395 22.2852 49.0258 22.3711 48.4242 22.3711Z" fill="#59BABA"/>
                    </svg>
                </a>
            </div>

            <!-- Header Content -->
            <div class="space-y-6">
                <h1 class="text-4xl font-extrabold tracking-tight text-[#161233]">
                    Get started in minutes
                </h1>
                <p class="text-slate-600 text-sm font-medium">
                    Aviaj Travel is free* &mdash; no platform fees.
                </p>

                <!-- Input field -->
                <form action="{{ route('demo-login') }}" method="GET" class="space-y-4 pt-4">
                    <div class="relative">
                        <label class="block text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-2">Work Email (name@company.com)</label>
                        <input type="email" id="email-input" required placeholder="name@company.com" class="w-full bg-[#FCFDFE] border border-slate-200 focus:border-[#59BABA] focus:ring-1 focus:ring-[#59BABA] pl-4 pr-4 py-3.5 rounded-lg text-sm text-[#0F172A] outline-none transition-all">
                    </div>
                    
                    <p class="text-[10px] text-slate-400 leading-normal">
                        By continuing, you agree to receive marketing communications. See our <a href="#" class="underline hover:text-[#59BABA]">Privacy Policy</a>
                    </p>

                    <button type="submit" id="btn-continue-email" class="w-full inline-flex items-center justify-center py-4 font-bold text-white bg-[#59BABA] hover:bg-[#48A5A5] rounded-full shadow-lg shadow-[#59BABA]/25 hover:shadow-xl hover:-translate-y-0.5 transition-all duration-200 text-sm tracking-wide text-center">
                        Continue with email
                    </button>
                </form>

                <!-- Separator -->
                <div class="flex items-center my-6">
                    <div class="flex-1 border-t border-slate-100"></div>
                    <span class="px-4 text-xs font-bold text-slate-400 uppercase tracking-widest">or</span>
                    <div class="flex-1 border-t border-slate-100"></div>
                </div>

                <!-- Google sign in button -->
                <a href="{{ route('demo-login') }}" id="btn-continue-google" class="w-full inline-flex items-center justify-center py-3.5 px-6 font-bold text-white bg-[#0C0A21] hover:bg-[#16133B] rounded-full shadow-md hover:-translate-y-0.5 transition-all duration-200 text-xs tracking-wider">
                    <!-- Google minimal G logo -->
                    <svg class="w-4 h-4 mr-2.5" viewBox="0 0 24 24" fill="currentColor">
                        <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                        <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                        <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.06H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.94l2.85-2.22.81-.63z" fill="#FBBC05"/>
                        <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.06l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                    </svg>
                    Continue with Google work account
                </a>

                <p class="text-[10px] text-slate-400 text-center leading-normal max-w-sm mx-auto">
                    By proceeding, you agree to the <a href="#" class="underline">Terms of Service</a>, <a href="#" class="underline">Privacy Policy</a>, and <a href="#" class="underline">Rewards policy</a>.
                </p>

                <!-- Outline Request Demo -->
                <div class="pt-4 flex flex-col items-center space-y-4">
                    <a href="#" id="btn-request-demo" class="w-full inline-flex items-center justify-center py-3.5 border border-slate-900 rounded-full font-bold text-xs text-[#0F172A] hover:bg-slate-50 transition-all duration-200 text-center">
                        Request a demo
                    </a>
                    
                    <span class="text-xs font-semibold text-slate-500">
                        Already have an account? <a href="{{ route('dashboard') }}" id="btn-login-redirect" class="font-extrabold text-[#0F172A] hover:text-[#59BABA] underline underline-offset-2 transition-colors">Log in</a>
                    </span>
                </div>
            </div>

            <!-- Footer disclaimer -->
            <div class="border-t border-slate-100 pt-6 mt-12 text-[10px] text-slate-400 leading-normal">
                *Aviaj Travel is free for eligible companies with up to 300 employees
            </div>
        </main>

        <!-- Right Half: Carousel / Slides Slider -->
        <aside id="get-started-aside" class="lg:col-span-6 bg-[#EEF2FF] flex flex-col justify-between p-8 sm:p-12 md:p-16 relative overflow-hidden" 
             x-data="{ 
                slide: 1,
                slides: [
                    {
                        title: 'Your one-stop shop',
                        desc: 'From booking to bookkeeping&mdash;give your company one place to manage travel and expense.'
                    },
                    {
                        title: 'Built-in travel policy',
                        desc: 'Keep travel spend fully controlled automatically, whether booking flights, lodging, or car rentals.'
                    },
                    {
                        title: 'Reconcile in real-time',
                        desc: 'Transactions swipe and auto-fill expense ledgers, cutting down bookkeeping hours to seconds.'
                    }
                ]
             }">
            
            <!-- Floating light curved background -->
            <div class="absolute inset-0 bg-gradient-to-tr from-[#59BABA]/10 to-transparent pointer-events-none"></div>

            <!-- Slider Header Logo list / brand logos -->
            <div class="flex items-center space-x-2 text-[11px] font-extrabold text-indigo-400/80 tracking-widest uppercase z-10">
                <span>AVIAJ</span>
                <span>&bull;</span>
                <span>TRAVEL & EXPENSE</span>
            </div>

            <!-- Slider Center mockup images & titles -->
            <div class="my-auto space-y-10 z-10 relative">
                
                <!-- Mockup graphics with prev/next navigation -->
                <div class="flex items-center justify-between">
                    <!-- Prev Arrow -->
                    <button @click="slide = slide === 1 ? 3 : slide - 1" id="slider-prev" class="w-10 h-10 rounded-full bg-white/70 hover:bg-white text-slate-700 shadow flex items-center justify-center transition-all">
                        &larr;
                    </button>

                    <!-- Mockup image slider overlay container -->
                    <div class="flex-1 max-w-sm mx-auto px-4 relative flex justify-center">
                        <div class="relative w-full aspect-[4/3] rounded-2xl overflow-hidden bg-white shadow-xl p-4 flex items-center justify-center border border-slate-100">
                            <!-- Show mockup assets sequentially -->
                            <div x-show="slide === 1" class="text-center space-y-4">
                                <img src="https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&q=80&w=400" class="h-32 object-cover rounded-xl shadow mx-auto">
                                <span class="text-xs font-bold text-[#161233] block">Book trips & record cards in seconds</span>
                            </div>
                            
                            <div x-show="slide === 2" class="text-center space-y-4" style="display: none;">
                                <img src="https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&q=80&w=400" class="h-32 object-cover rounded-xl shadow mx-auto">
                                <span class="text-xs font-bold text-[#161233] block">Automated corporate policy boundaries</span>
                            </div>

                            <div x-show="slide === 3" class="text-center space-y-4" style="display: none;">
                                <img src="https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&q=80&w=400" class="h-32 object-cover rounded-xl shadow mx-auto">
                                <span class="text-xs font-bold text-[#161233] block">Auto-reconciled receipt ledgers</span>
                            </div>
                        </div>
                    </div>

                    <!-- Next Arrow -->
                    <button @click="slide = slide === 3 ? 1 : slide + 1" id="slider-next" class="w-10 h-10 rounded-full bg-white/70 hover:bg-white text-slate-700 shadow flex items-center justify-center transition-all">
                        &rarr;
                    </button>
                </div>

                <!-- Active Slide Text contents -->
                <div class="text-center space-y-3 px-8">
                    <h3 class="text-xl font-extrabold text-[#161233] tracking-tight" x-text="slides[slide - 1].title"></h3>
                    <p class="text-slate-600 text-sm leading-relaxed max-w-md mx-auto" x-html="slides[slide - 1].desc"></p>
                </div>

                <!-- Navigation Indicator dots -->
                <div class="flex justify-center space-x-2.5">
                    <button @click="slide = 1" :class="slide === 1 ? 'bg-[#59BABA] w-6' : 'bg-slate-300 w-2.5'" class="h-2.5 rounded-full transition-all duration-200"></button>
                    <button @click="slide = 2" :class="slide === 2 ? 'bg-[#59BABA] w-6' : 'bg-slate-300 w-2.5'" class="h-2.5 rounded-full transition-all duration-200"></button>
                    <button @click="slide = 3" :class="slide === 3 ? 'bg-[#59BABA] w-6' : 'bg-slate-300 w-2.5'" class="h-2.5 rounded-full transition-all duration-200"></button>
                </div>
            </div>

            <!-- Footer: Trust Logo Slider -->
            <div class="z-10 mt-12 border-t border-slate-200/50 pt-6">
                <span class="text-[9px] uppercase font-bold text-slate-400 tracking-widest text-center block mb-4">Trusted globally by industry innovators</span>
                <div class="flex items-center justify-center gap-6 opacity-40 grayscale text-[11px] font-black tracking-widest">
                    <span>PINTEREST</span>
                    <span>HEINEKEN</span>
                    <span>AMPLITUDE</span>
                    <span>LYFT</span>
                    <span>OKTA</span>
                </div>
            </div>
        </aside>

    </div>

</body>
</html>
